/*
This node sets up flow context variables that will be used all over the flow to track state,
store tool information, ...

TI of all machines:

{"device_id":"D300L320218","beam":"a","timestamp":"2025-04-15T10:08:24.247Z","command":"TI","parameters":[
    "11PRT#1","3","5192","0","150","-1.00","0","200","1","5192","0","-9999","0",
    "21NOTCH#1","5","0","0","0","-1.00","0","200","0","0","0","-9999","0",
    "22PUNCH#2","5","0","0","0","-1.00","0","200","0","0","0","-9999","0"]}
{"device_id":"D300L320219","beam":"a","timestamp":"2025-04-15T10:13:12.767Z","command":"TI","parameters":[
    "11PRT#1","4","5171","0","150","-1.00","0","200","1","5171","0","-9999","0",
    "21NOTCH#1","5","0","0","0","-1.00","0","200","0","0","0","-9999","0",
    "22PUNCH#2","5","0","0","0","-1.00","0","200","0","0","0","-9999","0",
    "23SDT#1","5","0","0","0","-1.00","0","200","0","0","0","-9999","0"]}

*/



// Variable for all machine ids
const machines = [
    "D300L320218",
    "D300L320219",
    "D300L320194",
    ]
const monitoredCommands = ["SY", "ST", "FS", "CF", "ER", "JB"];
const beams = ["a", "b"]

flow.set("machines", machines);  // Can be used in other nodes
flow.set("beams", beams);  // Can be used in other nodes

const machineBeams = machines.map(machine => `${machine}${beams}`)
msg.machineBeams = machineBeams;

machines.forEach(machine => {
    // machine flow variable
    let flowContext = {
        "a": {
            "detailedState": "",
            "baseState": "",
            "timestamp_ts": 0,  // is used to trigger an beam state update at an minimum of each 2 seconds
            "latestJB": 0
        },
        "b": {
            "detailedState": "",
            "baseState": "",
            "timestamp_ts": 0,
            "latestJB": 0
        },
        "cutter": {
            "detailedState": "",
            "baseState": "",
            "timestamp_ts": 0,
            "latestJB": 0
        }
    };
    flow.set(machine, flowContext)

    // machine beam flow variable
    beams.forEach(beam => {
        const contextName = `${machine}-${beam}`;
        let beamFlowContext = {};

        // Initialize all monitored commands with empty arrays
        monitoredCommands.forEach(cmd => {
            beamFlowContext[cmd] = [0];
        });
        beamFlowContext["SY"] = [0];
        beamFlowContext["ST"] = [11];
        beamFlowContext["FS"] = [1];
        beamFlowContext["CF"] = [1, 1];
        beamFlowContext["ER"] = [];
        beamFlowContext["changeTimestamp"] = Date.now()
        beamFlowContext["JBHistory"] = [0];

        msg.payload = beamFlowContext;
        node.send(msg);
        flow.set(contextName, beamFlowContext)
    });
});

node.status({fill:"green", shape:"dot", text:"Flow context initialized"});

/*
This node transforms the incoming Socket message.
*/

let timestamp = Date.now();  // get timestamp
msg.timestamp = new Date(timestamp).toISOString();  // add timestamp as string
msg.timestamp_ms = timestamp;  // add timestamp as ms
msg.trigger = false;  // necessary to determine if it is a real command msg from cutter (see intervalTrigger)

msg.deviceId = msg.topic;  // set deviceId

/*
* Parse the command and all its parameters
*/

let cmd = msg.payload.replace(/[\r\n]/g, "");  // remove line breaks
cmd = cmd.trim()  // Trim the command to remove any leading/trailing spaces

let parsedCommand = {};  // array for parsed commands

// regular expression to extract the mnemonic and parameters
let match = cmd.match(/^([A-Z]{2})\s+(.*)$/); // Match 2 uppercase letters followed by one or more whitespaces
if (match) {
    let mnemonic = match[1]; // First group is the mnemonic
    let parameters = match[2] ? match[2].split(",").map(p => p.trim()) : []; // Split parameters by ',' and trim

    parsedCommand = { mnemonic, parameters };  // Add to parsed commands array
} else {
    node.warn(`Unrecognized command format: "${cmd}"`);  // Log unrecognized format for debugging purposes
}

msg.parsedCommand = parsedCommand;  // Assign parsed commands to the message payload
return msg;

/*
Sends the command and its parameters to a mqtt topic based on machine id and beam
*/

let machine = msg.topic
const cutter_id = machine.slice(0, -2)  // extract base cutter id without beam (-a / -b)
const beam = machine.slice(-1);  // extract beam

let baseTopic = `polipol/8200/szw/krt/${cutter_id}/beam-${beam}/commands/`;

let mnemonic = msg.parsedCommand.mnemonic
let parameters = msg.parsedCommand.parameters;
// Format the Date object to ISO string
msg.timestamp = new Date(msg.timestamp).toISOString();

// Construct the payload with the desired structure
msg.payload = {
    "device_id": cutter_id,
    "beam": beam,
    "timestamp": msg.timestamp,
    "command": mnemonic,
    "parameters": parameters
};

// Set the topic for the message
msg.topic = baseTopic + mnemonic;

return msg;

/*
Example payload of the status messages from TCP connections:

{
    "status": {
        "fill": "red",
        "shape": "ring",
        "text": "common.status.disconnected",
        "_session": {
            "type": "tcp",
            "id": "2f3e3f30b31e820b" 
        },
        "source": {
            "id": "8e42b6a85757df1c",
            "type": "tcp in",
            "name": "zund-cut04"
        }
    },
    "_msgid": "e1f08d1a4f110733"
}
*/
if (msg.status.text === "common.status.disconnected") {
    msg.topic = msg.status.source.name  // set topic to node name (machine id)
    msg.payload = "SY 10";  // Send a msg with payload set to SY 10 which is a custom system state
} else {
    return null;
}
return msg;

let SY = parseInt(msg.cmdStore.SY[0], 10);
let ST = parseInt(msg.cmdStore.ST[0], 10);
let FS = parseInt(msg.cmdStore.FS[0], 10);
let FEED_LENGTH = parseInt(msg.cmdStore.FS[2], 10); // Storing Feed Length Position
let JBcount = msg.cmdStore.JBHistory.length;  // length of JBHistory

const cutter_id = msg.deviceId.slice(0, -2)  // extract base cutter id without beam (-a / -b)
const beam = msg.beam;
const oppositeBeam = beam === "a" ? "b" : "a";  // get oppositeBeam
let latestStates = flow.get(cutter_id);  // get latestStates flow context

let baseState = latestStates[beam].baseState;
let detailedState = latestStates[beam].detailedState;

/*
Determine the beam state based on the commands.
If the beam was in handling feed before, a further heuristic is necessary:
After the feed is finished the beam (A) performs a movement to a position where he will
continue some work. The problem is, that the beam is sending Job Echos (JB) for these movement.
That would result in small "cutting" states, because normally the cutting ST is selected during that time.
A kind of "frozen time" should be applied to suppress this.
This frozen time will be of base state "handling" and detailed state "feed finished"
*/

function checkFrozenTime(changeTimestamp, frozenTime, currentTimestamp) {
    const duration = currentTimestamp - changeTimestamp;
    return duration < frozenTime;  // true = within frozen time / false = outside frozen time
};

if ([0, 1].includes(SY)) {
    /*
    Handle SY in [0, 1]. 0 and 1 means that the machine could possibly produce.
    The state the machine is currently in does matter, because of the frozen time for finshed handling.
    */
    if (JBcount > 0 && FS === 1) {
        let frozen = false;
        // Nur Beam A kann sich im Feed befinden → daher diese Logik nur bei Beam A anwenden
        if (beam === "a") {
            if (detailedState === "feed" || detailedState === "feed backwards") {
                baseState = "handling"
                detailedState = detailedState + " finished"  // add an "finished" to the state
                frozen = true;
            } else if (detailedState === "feed finished" || detailedState === "feed backwards finished") {
                frozen = checkFrozenTime(latestStates[beam].changeTimestamp, 5000, msg.timestamp_ms)
            }
        }
        // Falls das Kommando von Beam B kommt, prüfe, ob Beam A noch im Feed ist
        else if (beam === "b") {
            const beamAState = latestStates["a"].detailedState;
            // Falls Beam A noch in einem feed state ist, soll Beam B nicht in den Arbeitszustand wechseln
            if (beamAState === "feed" || beamAState === "feed continued" || beamAState === "feed finished" || beamAState === "feed backwards") {
                baseState = "idle";
                detailedState = "unknown";
                frozen = true;
            }
        }
        if (frozen === false) {
            baseState = "working";
            switch (ST) {
                case 11:
                    detailedState = "uv";
                    break;
                case 21:
                    detailedState = "notch";
                    break;
                case 22:
                    detailedState = "punch";
                    break;
                case 31:
                    detailedState = "cutting";
                    break;
                case 91:
                    baseState = "handling";
                    detailedState = "laser";
                    break;
            }
        }
    } else if (FS !== 1) {
        switch(FS) {
            case 0:
                baseState = "handling"
                if (FEED_LENGTH > 0) {  // Check if Feed is forward > 0 or backwards < 0
                    detailedState = "feed"
                }
                else {
                    detailedState = "feed backwards"
                }
                break;
            case 10:
            case 11:
                baseState = "handling"
                if (FEED_LENGTH > 0) {  // Check if Feed is forward > 0 or backwards < 0
                    detailedState = "feed continued"
                }
                else {
                    detailedState = "feed backwards continued"
                }
                break;
            case 20:
                baseState = "idle"
                detailedState = "feed suspended (external)"
                break;
            case 30:
            case 31:
            case 32:
            case 33:
                baseState = "idle"
                detailedState = "feed stopped"
                break;
        }
    } else if (FS === 1) {
        let frozen = false;

        if (detailedState === "feed" || detailedState === "feed backwards") {
            baseState = "handling";
            detailedState = detailedState + " finished";  // becomes "feed finished" or "feed backwards finished"
            frozen = true;
        } else if (detailedState === "feed finished" || detailedState === "feed backwards finished") {
            frozen = checkFrozenTime(latestStates[beam].changeTimestamp, 5000, msg.timestamp_ms);
        }
        if (frozen === false) {
            baseState = "idle";
            detailedState = "unknown";
        }
    }
} else if ([2, 4, 5].includes(SY)) {
    baseState = "idle";
    detailedState = "unknown";
    switch (FS) {
        case 20:
            baseState = "idle"
            detailedState = "feed suspended (external)"
            break;
        case 30:
        case 31:
        case 32:
        case 33:
            baseState = "idle"
            detailedState = "feed stopped"
            break;
    }
} else if ([9, 10].includes(SY)) {
    baseState = "offline";
    detailedState = "offline";
} else if (SY === 3) {
    baseState = "error";
    detailedState = "error";
}

msg.payload = {
    "device_id": cutter_id,
    "beam": beam,
    "timestamp": msg.timestamp,
    "base_state": baseState,
    "detailed_state": detailedState
};

msg.topic = `polipol/8200/szw/krt/${cutter_id}/beam-${beam}/state`;

// Check if baseState or detailedState has changed
const baseChanged = latestStates[beam].baseState !== baseState;
const detailedChanged = latestStates[beam].detailedState !== detailedState;
// If either changed, update the changeTimestamp
if (baseChanged || detailedChanged) {
    latestStates[beam].changeTimestamp = msg.timestamp_ms;
}

// Update latest States for the beam
latestStates[beam].baseState = baseState;
latestStates[beam].detailedState = detailedState;
latestStates[beam].latestJB = msg.cmdStore.JBHistory.length > 0 ? msg.cmdStore.JBHistory[JBcount - 1].timestamp : 0;
latestStates[beam].timestamp_ms = msg.timestamp_ms;

// Set the latestStates flow variable
flow.set(cutter_id, latestStates)

// Reset deviceId to cutter_id
msg.deviceId = cutter_id;

return msg;

// beamContextName is the deviceId (cutter + beam)
const beamContextName = msg.deviceId;
// Get flow context variable
let beamContext = flow.get(beamContextName);
msg.beam = msg.deviceId.slice(-1); // set msg.beam

// Check if it is not an trigger msg that was generated by the intervalTrigger Node
// Else compute the machine command msg
if (msg.trigger == false) {
    // Update cmd store
    if (msg.parsedCommand.mnemonic === "JB" && msg.parsedCommand.parameters[1] == "1") {
        // add timestamp in milliseconds to JBHistory and filter elements older than 2 seconds
        beamContext.JBHistory.push(msg.timestamp_ms);
    }
    // If Beam = a and command = SY check if SY changed from SY = 3 or changed to SY = 3
    // If so, send a further message to second output.
    else if (msg.parsedCommand.mnemonic === "SY" && msg.beam === "a") {
        const previousSY = beamContext.SY[0];
        const currentSY = msg.parsedCommand.parameters[0];
        if ((previousSY !== "3" && currentSY === "3") || (previousSY === "3" && currentSY !== "3")) {
            msg.SY = currentSY;
            msg.ER = beamContext.ER;
            node.send([null, msg])
        }
    }
    // Store parameters in beamContext
    beamContext[msg.parsedCommand.mnemonic] = msg.parsedCommand.parameters;
}

// Filter JB History and add timestamp_ts
beamContext.JBHistory = beamContext.JBHistory.filter(eventTime => eventTime >= Date.now() - 2000);
beamContext.timestamp_ts = Date.now();

msg.cmdStore = beamContext;

flow.set(beamContextName, beamContext);  // Set the updated beamContext

return [msg, null];

// get latestStates flow variable
let latestStates = flow.get(msg.deviceId);
let beamA = latestStates['a'];
let beamB = latestStates['b'];
let cutter = latestStates['cutter'];

// Determine state of whole cutter
if (beamA.baseState === "error" || beamB.baseState === "error") {
    cutter.baseState = "error";
    cutter.detailedState = "error";
} else if (beamA.baseState === "working" && beamB.baseState === "working") {
    // If both beams are working, the beam with the latest JB timestamp decides the detailed state
    cutter.baseState = "working";
    // Determine which beam has the newer job timestamp
    let latestBeam = beamA.latestJB >= beamB.latestJB ? beamA : beamB;
    cutter.detailedState = latestBeam.detailedState;
} else if (beamA.baseState === "handling") {
    // If beam A is in handling, whole cutter is in handling
    cutter.baseState = "handling";
    cutter.detailedState = beamA.detailedState;
} else if (beamA.baseState === "working" || beamB.baseState === "working") {
    // If one of the beams is working, set the cutter's state to "working"
    cutter.baseState = "working";
    // Set cutter's detailed state to the detailed state of the beam that's working
    if (beamA.baseState === "working") {
        cutter.detailedState = beamA.detailedState;
    } else {
        cutter.detailedState = beamB.detailedState;
    }
} else if (beamA.baseState === "idle" || beamB.baseState === "idle") {
    cutter.baseState = "idle";
    // Check if either beam has a non-"unknown" detailed state
    if (beamA.baseState === "idle" && beamA.detailedState !== "unknown") {
        cutter.detailedState = beamA.detailedState;
    } else if (beamB.baseState === "idle" && beamB.detailedState !== "unknown") {
        cutter.detailedState = beamB.detailedState;
    } else {
        cutter.detailedState = "unknown";  // If both are "unknown", set the cutter's state as "unknown"
    }
} else if (beamA.baseState === "offline" && beamB.baseState === "offline") {
    cutter.baseState = "offline";
    cutter.detailedState = "offline";
}

// Store latestStates Variable back to context
latestStates['cutter'] = cutter;
flow.set(msg.deviceId, latestStates)

// Get Timestamp for computation time measurement
msg.timestampLatest = Date.now()

msg.payload = {
    "device_id": msg.deviceId,
    "timestamp": msg.timestamp,
    "base_state": cutter.baseState,
    "detailed_state": cutter.detailedState,
    "computation_time_ms": (msg.timestampLatest - msg.timestamp_ms)
};

msg.topic = `polipol/8200/szw/krt/${msg.deviceId}/state`;

return msg;

// Function node to continuously check the beams' timestamp_ts attributes
