    let index1 = msg.ER?.[1] ?? null;
    let index2 = msg.ER?.[2] ?? null;

    msg.payload = {
        "device_id": cutter_id,
        "timestamp": msg.timestamp,
        "error_code": error_code,
        "category": category,
        "index1": index1,
        "index2": index2
    }
}
else {
